def is_2_5_smooth(num):
    if num <= 0:
        return False
    while num % 2 == 0:
        num //= 2
    while num % 5 == 0:
        num //= 5
    return num == 1

def get_prime_factorization(num):
    factors = {}
    d = 2
    temp = num
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def check_solution(n):
    # D(n) = (n+2) * ((n+1)^2 + 1)

    F_n = (n + 1)**2 + 1
    N_plus_2 = n + 2
    D_n = N_plus_2 * F_n

    # Condition 1: D(n) must be 2/5-smooth
    if not is_2_5_smooth(D_n):
        return None

    # If D(n) is smooth, we check the exponent conditions
    factors = get_prime_factorization(D_n)

    v2_Dn = factors.get(2, 0)
    v5_Dn = factors.get(5, 0)

    # Condition 2: v2(D(n)) <= 2(n+1)
    cond2 = v2_Dn <= 2 * (n + 1)

    # Condition 3: v5(D(n)) <= n+1
    cond3 = v5_Dn <= n + 1

    if cond2 and cond3:
        return n
    else:
        return None

solutions = []
# We iterate k = n+1 from 1 to 100, so n goes from 0 to 99.
for k in range(1, 101):
    n = k - 1

    # Pre-check based on task requirement: (n+1)^2 + 1 must be 2/5-smooth
    F_n = k**2 + 1
    if not is_2_5_smooth(F_n):
        continue

    # If F_n is 2/5-smooth, check the full conditions for D(n)
    result = check_solution(n)
    if result is not None:
        solutions.append(result)

print(solutions)
